window.STUDY_BFA_AI=[{"title":"Introduction à l’analyse financière et lecture du CPC","label":"CHAPITRE 1 — ANALYSE DU CPC","notes":[["Définition de l’analyse financière","L’analyse financière examine les informations comptables et financières d’une entreprise pour comprendre sa situation, sa performance et ses perspectives. Elle s’appuie notamment sur le CPC, le bilan et les ratios, puis tient compte des éléments qualitatifs : stratégie, marché et risques."],["À quoi sert-elle ?","Elle aide les dirigeants, investisseurs et créanciers à prendre des décisions : accorder un crédit, investir, adapter l’activité ou anticiper des difficultés. Une analyse doit déboucher sur une interprétation, pas seulement sur des calculs."],["Les étapes de l’analyse financière","Collecter les états financiers et leurs annexes ; évaluer la solvabilité, la rentabilité et la liquidité ; examiner la structure du financement ; comparer les ratios et les périodes ; établir des prévisions ; formuler des recommandations."],["Solvabilité, liquidité et rentabilité","Solvabilité : capacité à honorer ses dettes. Liquidité : disponibilité de ressources à court terme pour payer les échéances. Rentabilité : aptitude de l’activité ou des capitaux investis à générer un résultat. Ces notions sont liées mais différentes."],["Définition du CPC","Le Compte de Produits et Charges (CPC) est un état de synthèse qui regroupe les produits et les charges de l’exercice pour déterminer le résultat net. Il décrit la formation du résultat pendant une période ; le bilan présente une situation à une date donnée."],["Trois catégories du CPC","Exploitation : opérations liées à l’activité habituelle. Financier : produits et charges liés aux opérations financières. Non courant : opérations qui ne relèvent pas de l’activité courante. Chaque catégorie produit un résultat distinct."],["Les résultats du CPC","Résultat d’exploitation = produits d’exploitation − charges d’exploitation.\nRésultat financier = produits financiers − charges financières.\nRésultat courant = résultat d’exploitation + résultat financier.\nRésultat non courant = produits non courants − charges non courantes."],["Du résultat courant au résultat net","Résultat avant impôt = résultat courant + résultat non courant.\nRésultat net = résultat avant impôt − impôt sur les résultats. Un résultat positif est un bénéfice ; un résultat négatif est une perte. L’analyse porte aussi sur l’origine de ce résultat."]],"cards":[["Quel est l’objectif principal de l’analyse financière ?","Évaluer la situation et la performance financières d’une entreprise pour éclairer les décisions."],["Quels états financiers et outils servent à l’analyse financière ?","Les principaux états sont le CPC et le bilan, complétés notamment par les annexes. Les ratios sont des outils d’analyse calculés à partir des données financières."],["Quelle est la différence entre solvabilité et liquidité ?","Solvabilité : capacité à rembourser les dettes ; liquidité : moyens disponibles pour payer à court terme."],["Que mesure la rentabilité ?","La capacité de l’entreprise à générer un résultat par son activité ou les capitaux utilisés."],["Qu’est-ce que le CPC ?","Un état de synthèse qui présente les produits, les charges et la formation du résultat de l’exercice."],["Quelle est la différence entre le CPC et le bilan ?","Le CPC décrit le résultat sur une période ; le bilan décrit le patrimoine et le financement à une date donnée."],["Comment calculer le résultat d’exploitation ?","Produits d’exploitation − charges d’exploitation."],["Comment calculer le résultat financier ?","Produits financiers − charges financières."],["Comment calculer le résultat courant ?","Résultat d’exploitation + résultat financier."],["Comment calculer le résultat net ?","Résultat courant + résultat non courant − impôt sur les résultats."]],"quiz":[["Le résultat d’exploitation vaut 80 000 DH et le résultat financier −10 000 DH. Quel est le résultat courant ?",["70 000 DH","90 000 DH","80 000 DH"],0,"Résultat courant = 80 000 − 10 000 = 70 000 DH."],["Que cherche d’abord à comprendre une analyse financière ?",["La situation, les performances et les risques de l’entreprise","L’évolution du chiffre d’affaires sans examiner la structure du financement","La valeur du patrimoine sans analyser la rentabilité ni les risques"],0,"L’analyse met en relation plusieurs états et indicateurs pour apprécier la situation globale."],["Quel document explique la formation du résultat pendant un exercice ?",["Le bilan","Le CPC","L’inventaire physique seul"],1,"Le CPC retrace les produits et charges de la période."],["Quelle notion concerne surtout la capacité à payer les échéances proches ?",["La rentabilité","La productivité","La liquidité"],2,"La liquidité porte sur les moyens de paiement disponibles à court terme."],["À quoi correspond le résultat financier ?",["Produits financiers − charges financières","Ventes − achats revendus","Actif − passif"],0,"Il isole les produits et charges de nature financière."],["Quel résultat associe exploitation et financier ?",["Le résultat non courant","Le résultat courant","La valeur ajoutée"],1,"Résultat courant = résultat d’exploitation + résultat financier."],["Quel élément est déduit pour passer du résultat avant impôt au résultat net ?",["La production de l’exercice","Les stocks de marchandises","L’impôt sur les résultats"],2,"Résultat net = résultat avant impôt − impôt sur les résultats."],["Pourquoi comparer les résultats d’exploitation et financier ?",["Pour distinguer la performance de l’activité des effets du financement","Pour calculer directement le stock final","Pour remplacer toute analyse du bilan"],0,"Une activité rentable peut subir un résultat financier défavorable ; il faut distinguer les causes."],["Une analyse financière se termine idéalement par quoi ?",["Une simple recopie des états financiers","Des conclusions et recommandations justifiées","Une liste de chiffres sans interprétation"],1,"Les résultats doivent servir à éclairer les décisions."]],"map":[["Finalité","L’analyse financière évalue la situation, la performance et les perspectives pour éclairer les décisions."],["Sources","Le bilan et le CPC fournissent les données ; les ratios et informations qualitatives complètent l’analyse."],["Solvabilité","La solvabilité désigne la capacité à honorer ses dettes."],["Liquidité","La liquidité concerne les ressources disponibles pour payer les échéances proches."],["CPC","Le CPC explique la formation du résultat au cours de l’exercice."],["Exploitation","Résultat d’exploitation = produits d’exploitation − charges d’exploitation."],["Financier","Résultat financier = produits financiers − charges financières."],["Résultat net","Résultat net = résultat courant + résultat non courant − impôt sur les résultats."]],"number":1,"conceptLinks":[["CPC : produits − charges","L’exploitation et le financier forment le résultat courant ; le non-courant et l’impôt conduisent au résultat net."],["Bilan : emplois et ressources","Le bilan renseigne sur la structure de financement à une date donnée."],["Diagnostic : trois critères","La rentabilité mesure la performance ; liquidité et solvabilité évaluent la capacité de paiement."]]},{"title":"ESG : formation des résultats et principaux soldes","label":"CHAPITRE 1 — ANALYSE DU CPC","notes":[["Rôle de l’ESG et du TFR","L’État des Soldes de Gestion (ESG) décompose le résultat pour expliquer comment l’entreprise crée sa richesse et sa capacité d’autofinancement. Le Tableau de Formation des Résultats (TFR) présente l’enchaînement des soldes, de la marge brute au résultat net."],["Marge brute ou marge commerciale","Marge brute = ventes de marchandises en l’état − achats revendus de marchandises. Elle concerne surtout l’activité de négoce : acheter pour revendre sans transformation. Le taux de marge rapporté au chiffre d’affaires HT sert à apprécier la performance commerciale."],["Production de l’exercice","Production de l’exercice = ventes de biens et services produits ± variation des stocks de produits + immobilisations produites par l’entreprise pour elle-même. Elle mesure l’activité de production, vendue, stockée ou conservée pour les besoins internes."],["Consommation de l’exercice","Consommation de l’exercice = achats consommés de matières et fournitures + autres charges externes. Elle regroupe les ressources et services achetés à des tiers puis consommés pour réaliser l’activité."],["Valeur ajoutée (VA)","VA = marge brute + production de l’exercice − consommation de l’exercice. Elle mesure la richesse créée par l’entreprise avant sa répartition entre salariés, État, prêteurs et autres partenaires."],["Excédent brut d’exploitation (EBE)","EBE = VA + subventions d’exploitation − impôts et taxes − charges de personnel. L’EBE apprécie le surplus provenant de l’exploitation avant les dotations, les charges financières et les opérations non courantes. Si le solde est négatif, le cours parle d’insuffisance brute d’exploitation (IBE)."],["Résultat d’exploitation dans le TFR","Résultat d’exploitation = EBE + autres produits d’exploitation − autres charges d’exploitation + reprises d’exploitation (et transferts de charges) − dotations d’exploitation. Il mesure la performance de l’activité, indépendamment du financement et du non courant."],["Résultats financier, courant et non courant","Résultat financier = produits financiers − charges financières.\nRésultat courant = résultat d’exploitation + résultat financier.\nRésultat non courant = produits non courants − charges non courantes."],["Résultat net et lecture du TFR","Résultat net = résultat courant + résultat non courant − impôt sur les résultats. Pour interpréter le TFR, suivre la chaîne : marge brute, production, consommation, VA, EBE, résultat d’exploitation, financier, courant, non courant, net."]],"cards":[["À quoi sert l’État des Soldes de Gestion (ESG) ?","À expliquer comment l’activité produit les différents soldes et le résultat net."],["Quel tableau de l’ESG présente l’enchaînement des soldes jusqu’au résultat net ?","Tableau de Formation des Résultats : enchaînement des soldes de gestion."],["Comment calculer la marge brute commerciale ?","Ventes de marchandises en l’état − achats revendus de marchandises."],["Comment calculer la production de l’exercice ?","Ventes de biens et services produits ± variation des stocks de produits + immobilisations produites pour soi-même."],["Comment calculer la consommation de l’exercice ?","Achats consommés de matières et fournitures + autres charges externes."],["Comment calculer la valeur ajoutée (VA) ?","Marge brute + production de l’exercice − consommation de l’exercice."],["Que représente la valeur ajoutée ?","La richesse créée par l’entreprise grâce à son activité."],["Comment calculer l’EBE ?","VA + subventions d’exploitation − impôts et taxes − charges de personnel."],["Que signifie une insuffisance brute d’exploitation (IBE) ?","Un EBE négatif : l’exploitation ne dégage pas de surplus brut dans les conditions de l’exercice."],["Comment calculer le résultat d’exploitation à partir de l’EBE ?","EBE + autres produits − autres charges + reprises et transferts − dotations d’exploitation."],["Comment calculer le résultat non courant ?","Produits non courants − charges non courantes."],["Quelle chaîne de résultats faut-il retenir ?","VA → EBE → résultat d’exploitation → résultat courant → résultat net, avec les ajustements de chaque étape."]],"quiz":[["Une VA de 200 000 DH, des subventions d’exploitation de 10 000 DH, des impôts et taxes de 15 000 DH et des charges de personnel de 90 000 DH donnent quel EBE ?",["105 000 DH","125 000 DH","95 000 DH"],0,"EBE = 200 000 + 10 000 − 15 000 − 90 000 = 105 000 DH."],["Une entreprise achète des marchandises et les revend sans transformation. Quel solde mesure sa marge ?",["La CAF","La marge brute commerciale","La trésorerie nette"],1,"La marge brute compare ventes en l’état et achats revendus."],["Quel élément entre dans la production de l’exercice ?",["Les immobilisations produites par l’entreprise pour elle-même","Les dettes fournisseurs","Les dividendes distribués"],0,"La production inclut la production vendue, stockée et immobilisée."],["Quelles charges composent la consommation de l’exercice ?",["Les intérêts d’emprunt seulement","L’impôt sur les résultats","Les achats consommés et autres charges externes"],2,"La consommation correspond aux achats et services externes consommés."],["Quelle formule donne la valeur ajoutée ?",["VA = EBE − charges de personnel","VA = marge brute + production − consommation","VA = résultat net + impôt"],1,"La VA mesure la richesse produite après consommation des ressources externes."],["Quel élément est retranché de la VA pour calculer l’EBE ?",["Les charges de personnel","Les ventes de marchandises","Les produits financiers"],0,"L’EBE tient compte notamment des charges de personnel et des impôts et taxes."],["Quel poste est intégré pour passer de l’EBE au résultat d’exploitation ?",["Les dividendes distribués","Le capital social","Les dotations et reprises d’exploitation"],2,"Le résultat d’exploitation intègre les dotations et reprises liées à l’exploitation."],["Quel solde résulte de l’addition du résultat d’exploitation et du résultat financier ?",["Le résultat non courant","Le résultat courant","La marge commerciale"],1,"Le résultat courant regroupe les opérations habituelles d’exploitation et financières."],["À quoi sert le TFR dans une analyse ?",["À repérer les étapes qui créent ou réduisent le résultat","À calculer directement le fonds de roulement","À remplacer la comptabilité générale"],0,"Le TFR montre comment les différents soldes se forment."],["Quelle affirmation décrit correctement l’EBE ?",["Il est égal au résultat net après impôt","Il mesure la trésorerie bancaire","Il mesure le surplus brut de l’exploitation avant plusieurs ajustements"],2,"L’EBE précède notamment dotations, résultat financier et non courant."]],"map":[["ESG / TFR","L’ESG, notamment son tableau de formation des résultats, explique la formation progressive du résultat."],["Marge brute","Marge brute commerciale = ventes de marchandises − achats revendus de marchandises."],["Production","Ventes produites ± stocks + production immobilisée"],["Consommation","Consommation de l’exercice = achats consommés de matières et fournitures + autres charges externes."],["VA","Valeur ajoutée = marge brute commerciale + production de l’exercice − consommation de l’exercice."],["EBE","EBE = valeur ajoutée + subventions d’exploitation − impôts et taxes − charges de personnel."],["Résultat exploitation","EBE + autres produits − autres charges + reprises − dotations"],["Résultat courant","Résultat courant = résultat d’exploitation + résultat financier."],["Résultat net","Résultat net = résultat courant + résultat non courant − impôt sur les résultats."]],"number":2,"conceptLinks":[["De l’activité à la VA","Marge brute + production − consommation = richesse créée."],["De la VA à l’EBE","Ajouter les subventions d’exploitation ; retirer les impôts et taxes et les charges de personnel."],["De l’EBE au résultat net","Intégrer les autres éléments d’exploitation, le financier, le non-courant puis l’impôt."]]},{"title":"CAF et autofinancement","label":"CHAPITRE 1 — ANALYSE DU CPC","notes":[["Pourquoi calculer la CAF ?","La Capacité d’Autofinancement (CAF) représente une ressource interne issue de l’activité de l’entreprise. Le cours la présente comme une part de richesse non distribuée aux tiers. Elle aide à apprécier les moyens internes de financement."],["Ressources internes et externes","Le support distingue la CAF, ressource interne produite par l’entreprise, et les ressources externes : apports des associés, emprunts auprès des prêteurs et subventions de l’État. Une ressource interne ne nécessite pas de nouvel apport de capital ou de nouvel emprunt."],["Méthode additive : principe","Point de départ : résultat net.\nCAF = résultat net + dotations retenues − reprises retenues − produits de cession des immobilisations + valeur nette d’amortissement des immobilisations cédées.\nAttention : appliquer le périmètre des dotations et reprises précisé dans le cours, y compris les reprises sur subventions d’investissement à retrancher."],["Dotations et reprises dans la méthode additive","Le professeur précise les dotations et reprises visées : celles autres que relatives aux actifs circulants, aux passifs circulants et à la trésorerie ; les reprises sur subventions d’investissement sont aussi retranchées. Il faut donc identifier les postes concernés, et non ajouter toutes les dotations sans distinction."],["Pourquoi corriger les cessions d’immobilisations ?","Le prix de cession d’une immobilisation n’est pas un produit courant généré par l’activité. Dans la méthode additive du support, on retranche le produit de cession et on ajoute la valeur nette d’amortissement du bien cédé ou retiré."],["Méthode soustractive : principe","Point de départ : EBE (ou IBE).\nCAF = EBE + produits encaissables retenus − charges décaissables retenues.\nAppliquer les rubriques détaillées du tableau du professeur (voir ci-dessous)."],["Postes de la méthode soustractive dans le support","À ajouter selon le support : autres produits d’exploitation, transferts de charges, reprises d’exploitation relatives à l’actif circulant, produits financiers et produits non courants. À retrancher : autres charges d’exploitation, dotations d’exploitation relatives à l’actif circulant, charges financières, charges non courantes et impôt sur les résultats. Suivre les rubriques du tableau fourni en cours."],["Définition de l’autofinancement","L’autofinancement est la ressource interne effectivement conservée par l’entreprise.\nAutofinancement = CAF − distributions de bénéfices.\nNe pas confondre CAF et autofinancement ni CAF et trésorerie disponible."],["Comment interpréter la CAF ?","Une CAF positive indique une capacité de financement interne, mais ne prouve pas à elle seule que la banque dispose du même montant en espèces : les encaissements et paiements effectifs doivent aussi être examinés."]],"cards":[["Quelle ressource interne la CAF mesure-t-elle, et que signifie ce sigle ?","Capacité d’Autofinancement : ressource interne générée par l’activité de l’entreprise."],["Quelle est la différence entre CAF et emprunt ?","La CAF provient de l’entreprise ; un emprunt est une ressource externe fournie par un prêteur."],["Quel est le point de départ de la méthode additive de la CAF ?","Le résultat net de l’exercice."],["Quel est le principe de la méthode additive ?","Résultat net + dotations retenues − reprises retenues − produits de cession + VNA des immobilisations cédées."],["Pourquoi ajouter certaines dotations dans la méthode additive ?","Pour neutraliser des charges comptables retenues dans la méthode qui ont diminué le résultat net."],["Pourquoi retrancher certaines reprises dans la méthode additive ?","Pour neutraliser des produits comptables retenus dans la méthode qui ont augmenté le résultat net."],["Comment traiter le produit de cession d’une immobilisation dans la CAF additive ?","Le retrancher, puis ajouter la valeur nette d’amortissement de l’immobilisation cédée."],["Quel est le point de départ de la méthode soustractive ?","L’excédent brut d’exploitation (EBE) ou l’insuffisance brute d’exploitation (IBE)."],["Quel est le principe de la méthode soustractive ?","EBE + produits encaissables retenus − charges décaissables retenues dans le support."],["Qu’est-ce que l’autofinancement ?","La partie des ressources internes générées que l’entreprise conserve durablement pour financer ses activités."],["La CAF est-elle automatiquement égale au solde bancaire ?","Non. C’est un indicateur de capacité interne ; la trésorerie dépend aussi des encaissements et paiements."]],"quiz":[["CAF de 120 000 DH et distributions de 30 000 DH : quel autofinancement ?",["90 000 DH","150 000 DH","120 000 DH"],0,"Autofinancement = CAF − distributions = 90 000 DH."],["Quelle ressource est interne à l’entreprise ?",["Un emprunt bancaire","Un apport nouveau des associés","La CAF"],2,"La CAF est générée par l’entreprise elle-même."],["Quel solde sert de point de départ à la CAF additive ?",["Le résultat net","Le fonds de roulement","Le chiffre d’affaires"],0,"La méthode additive part du résultat net et effectue des ajustements."],["Que fait-on du produit de cession des immobilisations dans la méthode additive du cours ?",["On l’ajoute à l’EBE","On le retranche du résultat net corrigé","On le transforme en charge de personnel"],1,"Le support prévoit de retrancher le produit de cession."],["Que fait-on de la VNA d’une immobilisation cédée dans la CAF additive ?",["On la déduit des capitaux propres","On l’ajoute aux produits financiers","On l’ajoute dans le calcul de la CAF"],2,"Le support prévoit d’ajouter la valeur nette d’amortissement du bien cédé."],["Quel solde est utilisé au départ de la méthode soustractive ?",["L’EBE ou l’IBE","Le résultat financier","Le total du bilan"],0,"La méthode soustractive part de l’EBE/IBE."],["Quelle opération décrit la méthode soustractive ?",["CAF = actif − passif","CAF = EBE + produits retenus − charges retenues","CAF = marge brute + dettes"],1,"On ajuste l’EBE par les produits et charges prévus dans le tableau."],["Quelle est la différence entre CAF et autofinancement ?",["La CAF est une dette bancaire","L’autofinancement est toujours nul","La CAF mesure une capacité ; l’autofinancement est la ressource conservée"],2,"L’autofinancement correspond au surplus durablement conservé pour financer l’activité."],["Une CAF positive signifie-t-elle nécessairement un solde bancaire positif ?",["Non, la trésorerie dépend aussi des flux et des échéances","Oui, la CAF est le montant figurant au compte bancaire de l’entreprise","Oui, car toute ressource calculée est automatiquement encaissée"],0,"La CAF n’est pas le solde du compte bancaire."]],"map":[["CAF","La capacité d’autofinancement mesure la ressource interne potentielle générée par l’activité."],["Additive","CAF = résultat net + dotations retenues − reprises retenues − produits de cession + valeur nette d’amortissement des immobilisations cédées."],["Dotations / reprises","Retenir les postes précisés par le professeur"],["Cessions","Retrancher les produits de cession et ajouter la valeur nette d’amortissement des immobilisations cédées."],["Soustractive","CAF = EBE (ou IBE) + produits encaissables retenus − charges décaissables retenues, selon le périmètre du cours."],["Autofinancement","Autofinancement = CAF − distributions de bénéfices."],["Ressources externes","Apports, emprunts, subventions"],["Interprétation","La CAF ne correspond pas nécessairement au solde bancaire : elle n’est pas un indicateur de trésorerie disponible."]],"number":3,"conceptLinks":[["Méthode additive","Partir du résultat net ; neutraliser les dotations, reprises et cessions retenues."],["Méthode soustractive","Partir de l’EBE et intégrer les produits encaissables et charges décaissables retenus."],["CAF vers autofinancement","La distribution de dividendes réduit la ressource interne conservée ; la CAF n’est pas la trésorerie."]]},{"title":"Retraitements du CPC","label":"CHAPITRE 1 — ANALYSE DU CPC","notes":[["Pourquoi retraiter le CPC ?","Les retraitements améliorent la lecture économique des charges et produits et rendent les entreprises plus comparables. On déplace certains postes entre rubriques ; on ne confond pas ces reclassements d’analyse avec les écritures comptables ordinaires."],["Crédit-bail : principe","Le cours considère économiquement les immobilisations financées par crédit-bail comme faisant partie du capital productif de l’entreprise. Dans l’analyse, on intègre ces immobilisations à l’actif immobilisé."],["Crédit-bail : retraitement de la redevance","On retire la redevance de crédit-bail des autres charges externes, puis on la ventile entre dotations aux amortissements et charges financières pour le solde. Le but est de rapprocher la présentation de celle d’un financement classique."],["Personnel intérimaire","Les dépenses de personnel intérimaire ont la nature économique de charges de personnel. Le retraitement consiste à les retirer des autres charges externes et à les ajouter aux charges de personnel."],["Sous-traitance","Le support propose de retirer les charges de sous-traitance des autres charges externes et de les répartir entre achats pour la part « matières » et charges de personnel pour la part « main-d’œuvre ». Il faut connaître la composition de la prestation pour ventiler correctement."],["Subventions d’exploitation","Le support explique que les subventions d’exploitation sont exclues de la VA par le plan comptable marocain, puis présente un retraitement analytique possible : lorsqu’elles complètent le prix de vente, les rapprocher du chiffre d’affaires. C’est une proposition d’analyse, pas une nouvelle règle générale de comptabilisation."],["Effets à retenir","Déplacer une charge des autres charges externes vers les charges de personnel ou les dotations change certains soldes intermédiaires (comme VA ou EBE), même si le montant total de charges de l’exercice n’est pas nécessairement modifié."]],"cards":[["Pourquoi retraiter le CPC en analyse financière ?","Pour mieux représenter la réalité économique et comparer les performances entre entreprises."],["Pourquoi retraiter les redevances de crédit-bail dans l’analyse du CPC ?","Le retraitement restitue la nature économique de l’investissement financé par crédit-bail."],["Quel est le principe du retraitement du crédit-bail ?","Traiter économiquement le bien comme immobilisation et reclasser la redevance."],["Comment reclasser une redevance de crédit-bail ?","La retirer des autres charges externes et la répartir en dotations aux amortissements et charges financières."],["Pourquoi retraiter le personnel intérimaire ?","Parce que son coût a la nature économique d’une charge de personnel."],["Comment retraiter les frais de personnel intérimaire ?","Les retirer des autres charges externes et les ajouter aux charges de personnel."],["Comment retraiter les charges de sous-traitance ?","Les ventiler entre achats de matières et charges de personnel, selon la nature de la prestation."],["Pourquoi distinguer matières et main-d’œuvre dans la sous-traitance ?","Pour affecter chaque partie à sa nature économique et rendre les comparaisons plus pertinentes."],["Quel retraitement analytique des subventions le professeur présente-t-il ?","Les rapprocher du chiffre d’affaires lorsqu’elles constituent un complément du prix de vente."],["Un retraitement modifie-t-il toujours le total des charges ?","Non. Il peut seulement déplacer une charge d’une rubrique à une autre, modifiant les soldes intermédiaires."]],"quiz":[["Pourquoi retraiter les redevances de crédit-bail dans l’analyse du CPC ?",["Distinguer amortissement économique et charge financière","Supprimer toute charge de l’exercice","Transformer une charge en chiffre d’affaires"],0,"Le retraitement restitue la nature économique de l’investissement financé par crédit-bail."],["Quel est le but principal des retraitements du CPC ?",["Corriger uniquement les erreurs de calcul arithmétique du CPC","Rendre l’analyse économique plus comparable","Remplacer les catégories du CPC sans améliorer l’interprétation économique"],1,"Les retraitements rapprochent la présentation de la nature économique des opérations."],["Dans le retraitement du crédit-bail, où va la redevance ?",["Elle reste intégralement en autres charges externes sans ventilation","Elle est reclassée intégralement en dotations, sans composante financière","En dotations aux amortissements et charges financières"],2,"Le cours retire la redevance des charges externes puis la ventile entre amortissements et financier."],["Comment traite-t-on les frais de personnel intérimaire ?",["Des charges externes vers les charges de personnel","Des capitaux propres vers la trésorerie","Des produits vers les dettes"],0,"Le travail intérimaire est analysé comme une charge de personnel."],["Quel critère sert à répartir les charges de sous-traitance ?",["Le nombre d’associés","La part matières et la part main-d’œuvre","Le résultat financier de l’année"],1,"Le retraitement distingue les matières et le travail."],["Quelle affirmation correspond au retraitement des subventions décrit dans le cours ?",["Toute subvention est un emprunt","Les subventions doivent toujours être supprimées du CPC","Certaines subventions complétant le prix peuvent être rapprochées du chiffre d’affaires"],2,"Le professeur présente cette possibilité analytique, sans changer la règle comptable générale."],["Quel poste diminue quand on reclasse le coût du personnel intérimaire ?",["Les autres charges externes","Le capital social","Les ventes de marchandises"],0,"Le retraitement retire ce coût des charges externes pour le présenter en charges de personnel."],["Pourquoi le retraitement peut-il modifier l’EBE ?",["Parce qu’il supprime le bilan","Parce qu’il déplace des charges entre rubriques intervenant à des étapes différentes","Parce qu’il remplace le résultat net par le chiffre d’affaires"],1,"Les soldes intermédiaires dépendent de la nature et du classement des postes."],["Quelle différence faut-il retenir entre reclassement analytique et écriture comptable ?",["Aucune, ce sont exactement les mêmes opérations","Le reclassement oblige à modifier les factures d’origine","Le retraitement sert à analyser, sans modifier nécessairement les écritures du CPC publié"],2,"L’analyse financière recompose certains postes pour l’interprétation."]],"map":[["Objectif","Représentation économique et comparabilité"],["Crédit-bail","Charges externes → amortissements + charges financières"],["Immobilisation en crédit-bail","Intégration économique à l’actif immobilisé"],["Intérim","Charges externes → charges de personnel"],["Sous-traitance","Matières → achats ; main-d’œuvre → personnel"],["Subventions","Complément du prix : rattachement analytique possible au CA"],["Conséquences","Modification possible de VA et EBE"]],"number":4,"conceptLinks":[["Crédit-bail","Retraiter le loyer pour distinguer amortissement économique et financement."],["Intérim et sous-traitance","Identifier la nature économique des charges avant reclassement selon le cours."],["But des retraitements","Rendre les soldes comparables sans confondre reclassement analytique et écriture comptable."]]},{"title":"Bilan comptable et équilibre financier","notes":[["Objectif du diagnostic","L’analyse du bilan sert à apprécier si l’entreprise peut faire face à ses engagements. On étudie sa structure financière, son indépendance, sa solvabilité et sa liquidité. Solvabilité : capacité à honorer ses dettes ; liquidité : capacité à disposer de moyens de paiement à court terme."],["Lire le bilan comptable","L’actif indique les emplois : immobilisations, actif circulant hors trésorerie et trésorerie-actif. Le passif indique les ressources : financement permanent, passif circulant hors trésorerie et trésorerie-passif. Le total de l’actif est égal au total du passif."],["Fonds de roulement (FR)","FR = financement permanent − actif immobilisé. Un FR positif signifie que les ressources stables couvrent les immobilisations et laissent une marge pour financer l’activité. Un FR négatif indique que les immobilisations ne sont pas entièrement couvertes par des ressources stables."],["Besoin en fonds de roulement (BFR)","BFR = actif circulant hors trésorerie − passif circulant hors trésorerie. Les stocks et créances mobilisent de l’argent ; les dettes fournisseurs apportent un financement temporaire. BFR positif : besoin à financer ; BFR négatif : ressources cycliques supérieures aux emplois cycliques."],["Trésorerie nette (TN)","TN = trésorerie-actif − trésorerie-passif = FR − BFR.\nSi FR > BFR, la TN est positive.\nSi FR < BFR, elle est négative : il faut examiner le financement à court terme et les échéances, sans conclure automatiquement à une faillite."],["Bilan condensé en pourcentages","Poids d’un poste (%) = montant du poste / total du bilan × 100.\nLe pourcentage permet de comparer la structure du bilan."],["Interpréter avant de conclure","Un FR positif et une TN positive indiquent une couverture du BFR dans l’analyse de l’équilibre financier. Une TN très élevée n’est pas toujours optimale ; une TN négative n’est pas toujours une crise. Le professeur insiste sur la rotation des créances, des stocks et des dettes fournisseurs."]],"cards":[["À quoi sert l’analyse du bilan ?","À vérifier comment l’entreprise finance ses biens et si elle peut faire face à ses engagements."],["Que représente l’actif du bilan ?","Les emplois : ce que l’entreprise possède ou utilise, notamment immobilisations, stocks, créances et disponibilités."],["Que représente le passif ?","Les ressources qui financent l’actif : capitaux propres, dettes de financement, dettes courantes et trésorerie-passif."],["Comment calculer le fonds de roulement ?","FR = financement permanent − actif immobilisé. Il mesure la marge de financement stable après couverture des immobilisations."],["Comment calculer le BFR ?","BFR = actif circulant hors trésorerie − passif circulant hors trésorerie ; il mesure le besoin du cycle."],["Quelles sont les deux formules de la trésorerie nette ?","TN = trésorerie-actif − trésorerie-passif = FR − BFR."],["Que montre un fonds de roulement positif ?","Les ressources stables couvrent les immobilisations et laissent une marge pour financer l’activité."],["Pourquoi comparer FR et BFR ?","Parce que TN = FR − BFR : cette relation indique si le fonds de roulement couvre le besoin d’exploitation."],["Que signifie un BFR positif ?","Les emplois circulants hors trésorerie dépassent les ressources circulantes : l’entreprise doit financer cet écart."],["Comment lire un bilan condensé en pourcentages ?","Pour chaque poste : montant du poste ÷ total du bilan × 100. Cela montre son poids dans la structure financière."]],"quiz":[["FR = 90 000 DH ; BFR = 110 000 DH. Quelle conclusion est justifiée ?",["TN = −20 000 DH ; le FR ne couvre pas le BFR","TN = 20 000 DH ; excédent","TN = 200 000 DH ; équilibre"],0,"TN = FR − BFR = −20 000 DH. Cela ne suffit pas à conclure à une faillite."],["Que mesure le fonds de roulement (FR) ?",["La différence entre les ressources stables et les emplois stables","La somme des produits financiers","Le bénéfice avant impôt"],0,"FR = financement permanent − actif immobilisé."],["Que mesure le besoin en fonds de roulement (BFR) ?",["Le résultat courant","Le financement nécessaire aux décalages entre stocks, créances et dettes circulantes","La valeur des immobilisations seules"],1,"BFR = actif circulant hors trésorerie − passif circulant hors trésorerie."],["Quelle relation donne la trésorerie nette (TN) ?",["TN = VA − EBE","TN = produits − charges","TN = FR − BFR"],2,"La TN se vérifie aussi par trésorerie-actif − trésorerie-passif."],["Que signifie une TN négative ?",["Le BFR dépasse le FR et l’entreprise doit examiner son financement à court terme","L’entreprise est automatiquement en faillite","Les immobilisations ont une valeur nulle"],0,"Une TN négative appelle une analyse des échéances et du cycle, pas une conclusion automatique."],["Que signifie un FR négatif ?",["Les dettes fournisseurs sont nulles","Les ressources stables ne couvrent pas entièrement les immobilisations","L’entreprise dégage toujours une trésorerie positive"],1,"Les emplois stables dépassent les ressources stables."],["À quoi sert un bilan condensé en pourcentages ?",["À remplacer le CPC","À calculer les dividendes","À comparer le poids relatif des postes du bilan"],2,"Pourcentage = montant du poste ÷ total du bilan × 100."]],"map":[["Objectif","Solvabilité, liquidité et structure financière"],["Actif","L’actif regroupe les immobilisations, l’actif circulant hors trésorerie et la trésorerie-actif."],["Passif","Le passif regroupe le financement permanent, le passif circulant hors trésorerie et la trésorerie-passif."],["FR","Fonds de roulement = financement permanent − actif immobilisé."],["BFR","BFR = actif circulant hors trésorerie − passif circulant hors trésorerie."],["TN","Trésorerie nette = FR − BFR = trésorerie-actif − trésorerie-passif."]],"label":"CHAPITRE 2 — ANALYSE DU BILAN","number":5,"conceptLinks":[["Financement permanent − immobilisations","Le FR mesure la marge stable disponible après financement des immobilisations."],["Actif circulant hors trésorerie − passif circulant hors trésorerie","Le BFR mesure le besoin de financement du cycle hors trésorerie."],["FR − BFR = TN","Si le FR ne couvre pas le BFR, la trésorerie nette est négative."]]},{"title":"Bilan fonctionnel : cycles et retraitements","notes":[["Deux approches à distinguer","Le bilan fonctionnel classe les postes selon leur fonction : investissement, financement et exploitation. Le bilan financier classe l’actif par liquidité et le passif par exigibilité. Ne pas mélanger leurs règles de classement."],["Principe du bilan fonctionnel","Il étudie la continuité de l’exploitation et présente les emplois et ressources selon leur rôle économique. Il est établi en valeurs brutes et avant affectation du résultat, selon le cours."],["Fonction investissement","Elle regroupe les immobilisations en non-valeurs, incorporelles, corporelles et financières, sans les reclasser selon leur date de remboursement. Les immobilisations représentent les emplois stables."],["Fonction financement","Elle comprend les capitaux propres, les dettes de financement, les amortissements et les provisions. Les ressources stables financent d’abord les emplois stables, puis éventuellement une partie de l’exploitation."],["Fonction exploitation et hors exploitation","L’actif circulant d’exploitation comprend notamment stocks et créances clients. Le passif d’exploitation comprend notamment dettes fournisseurs. Les postes non liés à l’exploitation courante sont classés hors exploitation : créances diverses, dettes sur immobilisations, etc."],["Trésorerie fonctionnelle","Trésorerie-actif : disponibilités en banque, CCP et caisse. Trésorerie-passif : concours bancaires courants et soldes créditeurs de banques."],["Retraitements présentés par le professeur","Les emplois stables partent de l’actif immobilisé brut, corrigé notamment des primes de remboursement et des immobilisations acquises en crédit-bail. Les ressources stables partent du financement permanent et intègrent notamment amortissements et provisions, avec les ajustements liés au crédit-bail. Les règles détaillées figurent dans le tableau de retraitement du cours."],["FRF, BFRE et BFRHE","FRF = ressources stables − emplois stables.\nBFRE = actif circulant d’exploitation − passif circulant d’exploitation.\nBFRHE = actif circulant hors exploitation − passif circulant hors exploitation.\nBFR = BFRE + BFRHE = emplois cycliques − ressources cycliques."],["Trésorerie et interprétation","TN = trésorerie-actif − trésorerie-passif = FRF − BFR.\nFRF > 0 : ressources stables supérieures aux emplois stables.\nBFR > 0 : emplois cycliques supérieurs aux ressources cycliques. Les conditions de paiement clients et fournisseurs influencent le BFR."]],"cards":[["Quelle est la différence entre bilan fonctionnel et bilan financier ?","Fonctionnel : classement par cycles ; financier : par liquidité des actifs et exigibilité des dettes."],["Le bilan fonctionnel utilise-t-il les valeurs nettes ou brutes ?","Les valeurs brutes, selon le support du professeur, avant affectation du résultat."],["Quelles sont les trois grandes fonctions étudiées ?","Investissement, financement et exploitation."],["Pourquoi les amortissements apparaissent-ils dans les ressources stables ?","Le bilan fonctionnel retient les valeurs brutes et réintègre amortissements et provisions aux ressources stables."],["Où classer les stocks dans le bilan fonctionnel ?","Dans l’actif circulant d’exploitation : ce sont des emplois cycliques liés à l’activité."],["Où classer les dettes fournisseurs ?","Dans le passif circulant d’exploitation : elles financent temporairement le cycle d’exploitation."],["Comment calculer le FRF ?","FRF = ressources stables − emplois stables."],["Comment calculer le BFRE ?","BFRE = actif circulant d’exploitation − passif circulant d’exploitation."],["Comment calculer le BFRHE ?","BFRHE = actif circulant hors exploitation − passif circulant hors exploitation."],["Quel lien existe entre FRF, BFR et TN ?","TN = FRF − BFR, avec BFR = BFRE + BFRHE."]],"quiz":[["BFRE = 70 000 DH et BFRHE = −15 000 DH. Quel est le BFR total ?",["55 000 DH","85 000 DH","−55 000 DH"],0,"BFR = BFRE + BFRHE = 55 000 DH."],["Quel est le critère de classement du bilan fonctionnel ?",["La fonction économique des postes","La date de vente de chaque produit","La nationalité du fournisseur"],0,"On distingue investissement, financement, exploitation et hors exploitation."],["Quel poste est un emploi cyclique d’exploitation ?",["Capital social","Stock de marchandises","Emprunt bancaire à long terme"],1,"Le stock est lié au cycle achat-stockage-vente."],["Quel poste représente une ressource cyclique d’exploitation ?",["Créance client","Machine de production","Dette fournisseur"],2,"Le délai de paiement fournisseur constitue une ressource d’exploitation."],["Quelle relation définit le fonds de roulement fonctionnel (FRF) ?",["Ressources stables − emplois stables","Actif circulant − résultat net","Produits financiers − charges financières"],0,"FRF compare les ressources et emplois stables."],["Comment obtenir le BFR fonctionnel total ?",["BFRE − trésorerie-actif","BFRE + BFRHE","FRF + trésorerie-passif"],1,"On additionne le besoin d’exploitation et le besoin hors exploitation."],["Quelle relation permet de vérifier la TN fonctionnelle ?",["TN = BFRE + BFRHE","TN = produits − charges","TN = FRF − BFR"],2,"La trésorerie nette dépend du FRF et du BFR total."]],"map":[["Approche","Fonctions économiques, valeurs brutes"],["Investissement","Immobilisations et emplois stables"],["Financement","Capitaux, emprunts, amortissements, provisions"],["Exploitation","Stocks, clients et fournisseurs"],["Hors exploitation","Créances et dettes diverses"],["FRF","Ressources stables − emplois stables"],["BFR","BFRE + BFRHE"],["TN","FRF − BFR"]],"label":"CHAPITRE 2 — ANALYSE DU BILAN","number":6,"conceptLinks":[["Cycles stables","Les ressources stables financent les emplois stables ; leur différence donne le FRF."],["Cycles circulants","BFRE + BFRHE = BFR ; séparer exploitation et hors exploitation."],["Trésorerie","TN = FRF − BFR ; elle peut aussi se calculer par trésorerie-actif − trésorerie-passif."]]},{"title":"Bilan financier : liquidité, exigibilité et reclassements","notes":[["Objectif du bilan financier","Le bilan financier, ou bilan de liquidité, sert à apprécier la solvabilité et le risque de non-liquidité. L’actif est classé par liquidité croissante (capacité à être transformé en argent), le passif par exigibilité croissante (proximité de la date de paiement)."],["Différence essentielle avec le bilan fonctionnel","Le bilan financier cherche la valeur patrimoniale et le risque de paiement. Il est présenté en valeurs nettes et après répartition du résultat. Les postes sont reclassés selon leurs échéances réelles, notamment à plus ou moins d’un an."],["Stock outil ou stock de sécurité","Le stock minimum conservé durablement pour éviter une rupture de stock est considéré comme peu liquide. Il est retranché de l’actif circulant et ajouté à l’actif immobilisé."],["Créances et prêts selon leur échéance","Un prêt immobilisé remboursable à moins d’un an quitte l’actif immobilisé pour l’actif circulant. Une créance de l’actif circulant à plus d’un an est transférée vers l’actif immobilisé. On consulte notamment l’ETIC pour connaître les échéances."],["Titres et valeurs de placement (TVP)","Lorsque les TVP sont facilement négociables et immédiatement liquides, elles sont transférées de l’actif circulant vers la trésorerie-actif."],["Immobilisations en non-valeurs","Frais préliminaires, charges à répartir et primes de remboursement des obligations sont traités comme actifs fictifs dans l’approche financière du cours. On les retranche de l’actif et des capitaux propres."],["Écart de conversion actif","Il correspond à une perte de change latente. Le support distingue deux situations : si une provision pour risque de change couvre déjà la perte, aucun retraitement supplémentaire ; sinon, l’écart est retranché de l’actif et des capitaux propres."],["Plus-values et moins-values latentes","On corrige les valeurs des biens et créances pour rapprocher le bilan financier de la valeur réelle du patrimoine : une plus-value augmente l’actif concerné et les capitaux propres ; une moins-value les diminue."],["Répartition du résultat","Le bilan financier est établi après répartition. Les dividendes à distribuer quittent les capitaux propres pour le passif circulant hors trésorerie ; la part conservée reste dans les capitaux propres."],["Reclassement des dettes et comptes d’associés","La fraction des dettes de financement exigible à moins d’un an est transférée au passif circulant hors trésorerie. Une dette à plus d’un an est classée en financement permanent. Un compte d’associé créditeur peut devenir ressource stable s’il existe un engagement de longue durée."],["Autres corrections du passif","Le cours aborde les impôts différés ou latents sur certaines subventions et provisions, ainsi que les écarts de conversion passif (gains de change latents). Leur traitement dépend des précisions de l’énoncé et des règles de retraitement du support."],["Indicateurs du bilan financier","FR = capitaux propres + dettes à long et moyen terme − actif immobilisé.\nBFR = stocks + créances − passif circulant hors trésorerie.\nTN = trésorerie-actif − trésorerie-passif = FR − BFR."]],"cards":[["Quel est l’objectif du bilan financier ?","Apprécier la solvabilité et le risque de non-liquidité en reclassant les postes selon les échéances et leur valeur financière."],["Que signifie liquidité croissante à l’actif ?","Les éléments sont classés selon leur facilité à devenir de l’argent, des moins liquides aux plus liquides."],["Que signifie exigibilité croissante au passif ?","Les ressources et dettes sont classées selon la proximité de leur date de remboursement."],["Où classer le stock outil dans le bilan financier ?","Dans l’actif immobilisé : il reste durablement dans l’entreprise et est retranché de l’actif circulant."],["Comment reclasser un prêt immobilisé remboursable à moins d’un an ?","Le transférer de l’actif immobilisé à l’actif circulant, selon son échéance réelle."],["Que faire des TVP facilement cessibles ?","Les retirer de l’actif circulant et les ajouter à la trésorerie-actif."],["Comment traiter les immobilisations en non-valeurs ?","Les retrancher de l’actif et des capitaux propres : ce sont des actifs fictifs dans l’approche financière du cours."],["Comment traiter un écart de conversion actif sans provision ?","Le retirer de l’actif et des capitaux propres ; s’il est déjà provisionné, pas d’ajustement supplémentaire."],["Que deviennent les dividendes à distribuer ?","Ils quittent les capitaux propres et augmentent le passif circulant hors trésorerie."],["Où reclasser la part d’un emprunt exigible à moins d’un an ?","Du financement permanent vers le passif circulant hors trésorerie."],["Quand un compte d’associé créditeur peut-il être stable ?","Lorsqu’une convention matérialise l’engagement des associés de laisser les fonds durablement dans l’entreprise."],["Comment calculer le FR dans l’approche financière ?","FR = capitaux propres + dettes à long et moyen terme − actif immobilisé retraité."]],"quiz":[["Une fraction d’emprunt de 30 000 DH devient exigible dans six mois. Quel reclassement au bilan financier ?",["Du financement permanent au passif circulant hors trésorerie","Du passif vers les immobilisations","Du financement permanent aux capitaux propres"],0,"La fraction à moins d’un an relève des dettes à court terme."],["Un stock de sécurité conservé en permanence est reclassé où ?",["En trésorerie-actif","En actif immobilisé","En passif circulant"],1,"Le stock outil est durablement nécessaire à l’entreprise."],["Un prêt immobilisé remboursable à moins d’un an devient quoi ?",["Une dette à court terme","Un actif immobilisé à plus d’un an","Un élément de l’actif circulant"],2,"Une créance à moins d’un an est reclassée dans l’actif circulant."],["Que faire de TVP facilement cessibles ?",["Les transférer en trésorerie-actif","Les transférer aux capitaux propres","Les considérer comme dettes de financement"],0,"Ces titres sont rapidement transformables en disponibilités."],["Comment traiter les immobilisations en non-valeurs dans le bilan financier ?",["Les transférer à la trésorerie","Les retrancher de l’actif et des capitaux propres","Les ajouter aux dettes fournisseurs"],1,"Le cours les traite comme actifs fictifs dans l’approche financière."],["Un dividende à distribuer est classé où ?",["En actif circulant","En trésorerie-actif","En passif circulant hors trésorerie"],2,"La part distribuée devient une dette envers les associés."],["Que faire de la fraction d’un emprunt exigible à moins d’un an ?",["La transférer au passif circulant hors trésorerie","La transférer en trésorerie-actif","La classer parmi les stocks"],0,"On reclasse seulement la fraction à court terme."]],"map":[["Objectif","Solvabilité et risque de non-liquidité"],["Actif","Liquidité croissante"],["Passif","Exigibilité croissante"],["Stock outil","Actif circulant vers immobilisé"],["Prêts et créances","Reclasser selon échéance réelle"],["TVP liquides","Actif circulant vers trésorerie-actif"],["Actifs fictifs","Retrancher de l’actif et des capitaux propres"],["Dividendes","Capitaux propres vers passif circulant"],["Dettes","Moins d’un an vers passif circulant"]],"label":"CHAPITRE 2 — ANALYSE DU BILAN","number":7,"conceptLinks":[["Actif : liquidité","Reclasser les biens et créances selon leur délai réel de transformation en monnaie."],["Passif : exigibilité","Reclasser les dettes selon leur échéance ; les dividendes à distribuer deviennent une dette."],["Valeurs réelles et solvabilité","Éliminer les actifs fictifs et ajuster les valeurs selon le cours avant de calculer les indicateurs."]]},{"title":"Ratios de rentabilité et de structure financière","label":"CHAPITRE 3 — LA MÉTHODE DES RATIOS","number":3,"notes":[["Définition et utilisation","Un ratio est le rapport entre deux grandeurs significatives.\nIl complète le bilan, le CPC et l’ESG ; comparer dans le temps ou avec des entreprises du même secteur."],["Rentabilité commerciale nette","Résultat net / CA HT\nInterprétation : résultat net dégagé par dirham de chiffre d’affaires."],["Rentabilité commerciale brute","EBE / CA HT\nInterprétation : performance commerciale avant les effets du financement, des investissements et du non-courant."],["Rentabilité économique brute","EBE / Capitaux investis\nCapitaux investis = Immobilisations + BFR structurel\nInterprétation : rendement des moyens engagés."],["Rentabilité financière","Résultat net / Capitaux propres\nInterprétation : rendement des fonds propres."],["Rentabilité pour les actionnaires","Dividendes distribués / Capital social (ou personnel)\nInterprétation : dividendes rapportés au capital."],["Ratio de fonds de roulement","Ressources stables / Immobilisations\nRepère du cours : > 1. Les ressources stables couvrent alors les immobilisations."],["Endettement global","Total des dettes / Total du passif\nInterprétation : part du passif financée par la dette."],["Structure de l’endettement","Dettes de financement / Total des dettes\nInterprétation : poids des dettes de financement dans l’endettement global."],["Coût de l’endettement","Charges financières / Total des dettes\nInterprétation : coût des dettes selon le ratio du support."],["Autonomie financière","Capitaux propres / Financement permanent\nRepère du cours : > 50 %."],["Capacité de remboursement (1)","Capitaux propres / Dettes de financement\nRepère du cours : > 1 en principe."],["Capacité de remboursement (2)","Dettes de financement / CAF\nInterprétation : nombre d’années théoriques de CAF.\nRepère du cours : ne pas dépasser 4 à 5 fois."]],"cards":[["Rentabilité commerciale nette : formule ?","Résultat net / chiffre d’affaires HT."],["Pourquoi EBE / CA HT complète-t-il résultat net / CA HT ?","Il isole mieux la rentabilité de l’exploitation, avant financement et éléments non courants."],["Rentabilité économique brute : formule du cours ?","EBE / capitaux investis, avec capitaux investis = immobilisations + BFR structurel."],["Quel ratio concerne directement les capitaux des propriétaires ?","Résultat net / capitaux propres : rentabilité financière."],["Que signifie ressources stables / immobilisations > 1 ?","Les ressources stables couvrent les immobilisations et laissent une marge pour le cycle d’exploitation."],["Comment mesurer l’endettement global ?","Total des dettes / total passif."],["Quel ratio mesure l’autonomie financière ?","Capitaux propres / financement permanent (repère du cours : > 50 %)."],["Que signifie dettes de financement / CAF = 5 ?","Une dette équivalente à cinq années de CAF, à CAF constante, avant autres considérations."]],"quiz":[["Dettes de financement de 600 000 DH et CAF annuelle de 150 000 DH : quelle durée théorique ?",["4 ans","0,25 an","5 ans"],0,"600 000 / 150 000 = 4. Ce ratio suppose une CAF constante."],["Lequel mesure la rentabilité commerciale d’exploitation ?",["EBE / CA HT","Résultat net / capitaux propres","Dettes de financement / CAF"],0,"Le cours utilise EBE / CA HT pour la rentabilité commerciale liée à l’exploitation."],["Une entreprise finance toutes ses immobilisations par des ressources stables et dispose encore d’une marge. Son ratio ressources stables / immobilisations est :",["Nécessairement nul","Supérieur à 1","Toujours inférieur à 1"],1,"Un ratio supérieur à 1 indique une couverture des immobilisations par les ressources stables."],["Quel ratio exprime le poids de toutes les dettes dans le passif ?",["Charges financières / dettes","Dettes de financement / CAF","Total des dettes / total passif"],2,"Ce rapport est appelé endettement global dans le cours."],["Quel rapport donne une durée théorique de remboursement ?",["Dettes de financement / CAF","Capitaux propres / financement permanent","Résultat net / CA HT"],0,"Le cours indique un repère de 4 à 5 années de CAF."],["Quel ratio mesure le rendement des fonds propres ?",["EBE / CA HT","Résultat net / capitaux propres","Ressources stables / immobilisations"],1,"La rentabilité financière met le résultat en rapport avec les capitaux propres."],["Quels éléments forment les capitaux investis pour le ratio EBE / capitaux investis ?",["Stocks + chiffre d’affaires","Dettes à court terme + trésorerie","Immobilisations + BFR structurel"],2,"Le cours définit ici les capitaux investis par les immobilisations majorées du BFR structurel."]],"map":[["Méthode","Comparer deux grandeurs, dans le temps et dans l’espace"],["Commerciale","Résultat net / CA HT ; EBE / CA HT"],["Économique","EBE / capitaux investis"],["Financière","Résultat net / capitaux propres"],["Financement","Ressources stables / immobilisations"],["Endettement","Dettes / passif ; dettes de financement / total dettes"],["Autonomie","Capitaux propres / financement permanent"],["Remboursement","Dettes de financement / CAF"]],"conceptLinks":[["Rentabilité","Comparer le résultat au CA, aux moyens investis ou aux capitaux propres selon l’indicateur."],["Structure","Le financement stable doit couvrir les immobilisations ; l’autonomie mesure le poids des fonds propres."],["Remboursement","Dettes de financement / CAF exprime une durée théorique ; le cours propose un repère de 4 à 5 ans."]]},{"title":"Ratios d’activité, valeur ajoutée et liquidité","label":"CHAPITRE 3 — LA MÉTHODE DES RATIOS","number":3,"notes":[["Principe des ratios d’activité","Les durées du cours sont calculées sur 360 jours.\nStock moyen = (Stock initial + Stock final) / 2 (lorsque seules ces deux valeurs sont disponibles)."],["Stock de marchandises","(Stock moyen de marchandises / Achats revendus de marchandises) × 360\nDurée moyenne du stockage commercial, en jours."],["Stock de matières et fournitures","(Stock moyen de matières et fournitures / Achats consommés de matières et fournitures) × 360\nDurée moyenne du stockage industriel, en jours."],["Stock de produits en cours","(Stock moyen de produits en cours / Production vendue) × 360\nDurée de stockage selon le support."],["Stock de produits finis","(Stock moyen de produits finis / Production vendue) × 360\nDurée de stockage selon le support."],["Délai clients","(En-cours clients / Ventes TTC) × 360\nDélai d’encaissement en jours."],["Délai fournisseurs","(En-cours fournisseurs / Achats TTC) × 360\nDélai de paiement en jours."],["Part du personnel","Charges de personnel / Valeur ajoutée\nPart de la richesse créée destinée au personnel."],["Part de l’État","(IS + Impôts et taxes) / Valeur ajoutée\nPart destinée à l’État."],["Part des bailleurs de fonds","Charges financières / Valeur ajoutée\nPart destinée aux bailleurs de fonds."],["Part des actionnaires","Dividendes / Valeur ajoutée\nPart destinée aux actionnaires."],["Part de l’entreprise","Autofinancement / Valeur ajoutée\nPart conservée par l’entreprise."],["Liquidité générale","Actif circulant / Dettes à court terme (DCT)\nMesure la couverture des engagements à court terme."],["Liquidité relative","(Créances de l’actif circulant + Trésorerie) / DCT\nExclut les stocks."],["Liquidité immédiate","Trésorerie / DCT\nMesure la couverture par la seule trésorerie."]],"cards":[["Durée de stockage des marchandises ?","Stock moyen de marchandises / achats revendus de marchandises × 360 jours."],["Durée des matières premières et fournitures ?","Stock moyen de matières et fournitures / achats consommés de matières et fournitures × 360 jours."],["Formule du délai clients ?","En-cours clients / ventes TTC × 360 jours."],["Formule du délai fournisseurs ?","En-cours fournisseurs / achats TTC × 360 jours."],["Quel est le sens d’un délai clients plus élevé ?","Les créances restent en moyenne plus longtemps à encaisser ; le besoin de financement peut augmenter."],["Comment mesurer la part du personnel dans la VA ?","Charges de personnel / valeur ajoutée."],["Comment mesurer la part conservée par l’entreprise ?","Autofinancement / valeur ajoutée."],["Quelle est la différence entre liquidité générale, relative et immédiate ?","Générale : actif circulant ; relative : créances + trésorerie ; immédiate : seule trésorerie, chacune sur DCT."]],"quiz":[["En-cours clients = 60 000 DH, ventes TTC annuelles = 720 000 DH. Quel délai clients sur 360 jours ?",["30 jours","60 jours","12 jours"],0,"60 000 / 720 000 × 360 = 30 jours."],["Pour calculer un délai moyen clients dans le cours, on utilise :",["Ventes HT / en-cours clients","En-cours clients / ventes TTC × 360","Stock moyen / ventes TTC"],1,"Le dénominateur est constitué des ventes TTC, selon le support."],["Un délai fournisseurs passe de 30 à 45 jours. Cela indique généralement :",["Un allongement du crédit fournisseurs","Une baisse certaine des achats","Un raccourcissement du crédit fournisseurs"],0,"Le délai mesure la durée moyenne du crédit accordé par les fournisseurs."],["Quelle formule correspond à la part de l’État dans la valeur ajoutée ?",["Dividendes / VA","Charges financières / VA","(IS + impôts et taxes) / VA"],2,"Le cours inclut l’IS et les impôts et taxes dans la part de l’État."],["La liquidité immédiate utilise au numérateur :",["Les disponibilités / trésorerie","Tout l’actif circulant","Les créances et les stocks"],0,"La liquidité immédiate compare la trésorerie aux dettes à court terme."],["Quel ratio de liquidité exclut les stocks mais conserve les créances ?",["Liquidité générale","Liquidité relative","Liquidité immédiate"],1,"La liquidité relative retient créances de l’actif circulant et trésorerie."],["Comment calculer la durée de stockage des produits finis selon le support ?",["En-cours fournisseurs / achats TTC × 360","Stock moyen / achats revendus × 360","Stock moyen de produits finis / production vendue × 360"],2,"La formule du document utilise la production vendue au dénominateur."]],"map":[["Stocks commerciaux","Durée (jours) = (stock moyen de marchandises / achats revendus de marchandises) × 360."],["Stocks industriels","Durée (jours) = (stock moyen de matières et fournitures / achats consommés de matières et fournitures) × 360."],["Produits","Durée (jours) = (stock moyen de produits en cours ou finis / production vendue) × 360, selon le support."],["Clients","Délai clients (jours) = (en-cours clients / ventes TTC) × 360."],["Fournisseurs","Délai fournisseurs (jours) = (en-cours fournisseurs / achats TTC) × 360."],["Valeur ajoutée","Personnel, État, bailleurs, actionnaires, entreprise"],["Liquidité générale","Actif circulant / DCT"],["Liquidité relative","(Créances + trésorerie) / DCT"],["Liquidité immédiate","Trésorerie / DCT"]],"conceptLinks":[["Stocks → encaissements","La durée de stockage et le délai clients immobilisent des ressources ; les délais fournisseurs peuvent financer le cycle."],["Valeur ajoutée → bénéficiaires","Le personnel, l’État, les prêteurs, les actionnaires et l’entreprise se partagent la richesse créée."],["Liquidité : trois niveaux","Générale : actifs circulants ; relative : créances et trésorerie ; immédiate : seule trésorerie."]]},{"title":"Rentabilité économique, financière et effet de levier","label":"CHAPITRE 3 — LA MÉTHODE DES RATIOS","number":3,"notes":[["Principe","L’effet de levier explique l’incidence de l’endettement sur la rentabilité des capitaux propres."],["Actif économique","Actif économique = Immobilisations corporelles et incorporelles d’exploitation + Biens en crédit-bail d’exploitation + Besoin de financement de l’exploitation\nLe cours présente également la définition générale : actifs immobilisés + BFR."],["Rentabilité économique brute (ROI)","EBE / Actif économique brut (ou net)\nLe support mentionne aussi le résultat net après impôt / actif économique brut (ou net)."],["Rentabilité économique retenue pour le levier","Re = Résultat d’exploitation / Actif économique\nConvention donnée à la page 18 du support."],["ROA","Résultat net / Actif total\nNe pas confondre avec Re."],["Rentabilité financière","Rcp = Résultat net / Capitaux propres\nRendement des fonds propres."],["Formule du professeur (page 21)","Rcp = Re + (Re − i) × (D / CP) × (1 − t)\nD : dettes totales ; CP : capitaux propres ; i : taux d’intérêt moyen avant IS ; t : taux d’impôt.\nAttention : la page 21 définit Re après IS, alors que la page 18 utilise le résultat d’exploitation. Clarifier la convention avec le professeur avant application numérique ; ne pas mélanger les taux avant et après impôt."],["Lecture du terme de levier","Re > i : terme positif.\nRe = i : terme nul.\nRe < i : terme négatif.\nCes signes supposent D / CP positif et un taux d’impôt inférieur à 100 %."],["Limite","Une rentabilité financière accrue ne garantit pas la capacité de remboursement. Examiner également la CAF et le niveau d’endettement."]],"cards":[["Qu’appelle-t-on actif économique ?","Les moyens nécessaires à l’exploitation, dont les immobilisations d’exploitation et le besoin de financement d’exploitation."],["Dans la formule du cours, à conventions cohérentes, Re = i et D/CP > 0. Quel est le terme de levier ?","Le facteur Re − i vaut zéro."],["Comment calcule-t-on Re pour l’effet de levier dans ce cours ?","La page 18 retient le résultat d’exploitation / actif économique ; la page 21 emploie une convention après IS. Vérifier avec le professeur avant d’appliquer le levier."],["Quelle est la différence entre Re et ROA ?","Re : résultat d’exploitation / actif économique ; ROA : résultat net / actif total."],["Comment calculer Rcp ?","Résultat net / capitaux propres."],["Que représente i dans la formule de levier ?","Le taux d’intérêt moyen des dettes avant impôt."],["Que représente D / CP ?","Le rapport dettes totales / capitaux propres, qui mesure l’intensité de l’endettement dans la formule."],["Quelle condition rend le terme de levier positif ?","Re > i, lorsque les conventions de taux de la formule sont cohérentes."],["Pourquoi un effet de levier positif n’est-il pas sans risque ?","Les intérêts et remboursements restent dus même si la rentabilité se détériore."]],"quiz":[["Dans la formule du cours, à conventions cohérentes, Re = i et D/CP > 0. Quel est le terme de levier ?",["Nul","Positif","Négatif"],0,"Le facteur Re − i vaut zéro."],["Dans l’expression (Re − i) × D / CP × (1 − t), si Re < i, le terme d’effet de levier est :",["Négatif si D/CP est positif","Toujours positif","Toujours nul"],0,"Lorsque le rendement économique est inférieur au coût de la dette, le levier dégrade la rentabilité des capitaux propres dans la relation présentée."],["Le ROA dans le support est :",["Résultat d’exploitation / actif économique","Résultat net / actif total","Résultat net / capitaux propres"],1,"Le cours distingue explicitement ROA et rentabilité économique Re."],["La rentabilité financière Rcp est :",["EBE / chiffre d’affaires","Résultat d’exploitation / actif économique","Résultat net / capitaux propres"],2,"Elle rapporte le résultat net aux fonds investis par les propriétaires."],["Si Re = i dans la relation du support, l’effet lié à la dette est :",["Nul","Toujours positif","Toujours négatif"],0,"Le facteur Re − i est égal à zéro."],["Que représente CP dans la formule ?",["Crédits de paiement","Capitaux propres","Charges de personnel"],1,"CP signifie capitaux propres."],["Pour interpréter un levier favorable, il faut aussi surveiller :",["Uniquement le CA HT","Uniquement la VA","Le niveau d’endettement et la capacité de remboursement"],2,"L’endettement peut augmenter le risque financier malgré une rentabilité apparente plus forte."]],"map":[["Actif économique","Immobilisations d’exploitation + besoin de financement"],["Re","Page 18 : résultat d’exploitation / actif économique. La convention après IS de la page 21 doit être clarifiée."],["ROA","Résultat net / actif total"],["Rcp","Résultat net / capitaux propres"],["Formule","Formule du support : Rcp = Re + (Re − i) × (D / CP) × (1 − t). Convention de Re à confirmer avec le professeur avant application numérique."],["Re > i","À conventions de taux cohérentes, Re > i donne un terme de levier positif."],["Re = i","À conventions cohérentes, Re = i annule le terme de levier."],["Re < i","À conventions cohérentes, Re < i donne un terme de levier négatif."],["Prudence","Rentabilité et risque de remboursement"]],"conceptLinks":[["Rentabilités à distinguer","Re rapporte le résultat d’exploitation à l’actif économique ; Rcp rapporte le résultat net aux fonds propres."],["Dette → effet de levier","Le signe du terme de levier dépend de Re − i, à conventions de taux cohérentes."],["Risque et fiscalité","L’endettement amplifie le risque ; ne pas mélanger taux avant et après IS."]]}];
